mapper.select:
SELECT id, workspace_id, recipient_user_id, project_id, kind, title, body, route_name,
       (read_at IS NOT NULL) AS "read", created_at
FROM notifications
WHERE workspace_id = #{workspaceId}
  AND recipient_user_id = #{userId}
ORDER BY created_at DESC, id DESC

mapper.insert:
INSERT INTO notifications(
    workspace_id, recipient_user_id, project_id, kind, title, body, route_name
) VALUES (
    #{workspaceId}, #{recipientUserId}, #{projectId}, #{kind}, #{title}, #{body}, #{routeName}
)

mapper.update:
UPDATE notifications
SET read_at = COALESCE(read_at, CURRENT_TIMESTAMP)
WHERE id = #{id}
  AND workspace_id = #{workspaceId}
  AND recipient_user_id = #{userId}

UPDATE notifications
SET read_at = CURRENT_TIMESTAMP
WHERE workspace_id = #{workspaceId}
  AND recipient_user_id = #{userId}
  AND read_at IS NULL
